import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';

// ═══════════════════════════════════════════════════════════════════════════════
// Types & constants
// ═══════════════════════════════════════════════════════════════════════════════

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1200;
const CX = W / 2;

const COLORS = {
  input:   { fill: '#e8f5e9', stroke: '#4caf50' },
  proj:    { fill: '#e3f2fd', stroke: '#1976d2' },
  conv:    { fill: '#e8eaf6', stroke: '#3949ab' },
  ssm:     { fill: '#fce4ec', stroke: '#c2185b' },
  gate:    { fill: '#fff3e0', stroke: '#f57c00' },
  weight:  { fill: '#f1f5f9', stroke: '#64748b' },
  output:  { fill: '#f3e5f5', stroke: '#7b1fa2' },
  residual:{ fill: '#e8f5e9', stroke: '#4caf50' },
  mul:     { fill: '#fff3e0', stroke: '#f57c00' },
  delta:   { fill: '#e0f7fa', stroke: '#00838f' },
  state:   { fill: '#fff8e1', stroke: '#f9a825' },
  text:    'var(--text)',
  muted:   'var(--text-muted)',
};

const BOX_H = 52;
const BOX_W = 960;
const MAT_H = 60;
const VEC_H = 28;
const VEC_W = 120;
const WEIGHT_W = 96;
const WEIGHT_H = 70;
const SEQ_W = 140;
const GROUP_GAP = 80;
const BOX_TO_ROW_GAP = 44;
const VERTICAL_ARROW_LEN = 80;
const ROW_EQ_GAP = 44;
const RESIDUAL_OFFSET = 320;

interface MambaStep extends StepInfo {}

interface RenderResult {
  steps: MambaStep[];
  y: number;
}

interface MambaParams {
  dModel: number;
  seqLen: number;
  stateDim: number;
  dInner: number;
  deltaRank: number;
  variant: string;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Low-level helpers
// ═══════════════════════════════════════════════════════════════════════════════

function lbl(
  g: Gsel,
  x: number,
  y: number,
  text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function startGroup(g: Gsel, className: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel,
  cx: number,
  y: number,
  stepNum: number,
  title: string,
  formula: string,
  fill: string,
  stroke: string,
  width = BOX_W
): number {
  const grp = g.append('g');
  grp
    .append('rect')
    .attr('x', cx - width / 2)
    .attr('y', y)
    .attr('width', width)
    .attr('height', BOX_H)
    .attr('rx', 8)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);

  grp.append('circle')
    .attr('cx', cx - width / 2 + 22)
    .attr('cy', y + BOX_H / 2)
    .attr('r', 14)
    .attr('fill', stroke);
  lbl(grp, cx - width / 2 + 22, y + BOX_H / 2 + 1, String(stepNum), { size: 13, weight: '700', color: '#fff' });

  lbl(grp, cx - width / 2 + 44, y + BOX_H / 2 - 1, title, {
    size: 15,
    weight: '600',
    color: 'var(--text)',
    anchor: 'start',
  });
  lbl(grp, cx + width / 2 - 14, y + BOX_H / 2 - 1, formula, {
    size: 11,
    color: 'var(--text-muted)',
    font: 'monospace',
    anchor: 'end',
  });
  return y + BOX_H;
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle')
    .attr('cx', cx)
    .attr('cy', cy)
    .attr('r', 14)
    .attr('fill', '#fff')
    .attr('stroke', color)
    .attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 12, weight: '700', color });
}

function hexWithAlpha(hex: string, alpha: number): string {
  const v = hex.replace('#', '');
  const bigint = parseInt(v, 16);
  const r = (bigint >> 16) & 255;
  const gg = (bigint >> 8) & 255;
  const b = bigint & 255;
  return `rgba(${r}, ${gg}, ${b}, ${alpha})`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Matrix helpers
// ═══════════════════════════════════════════════════════════════════════════════

function drawSeqMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.input.fill,
  stroke = COLORS.input.stroke
): void {
  drawMatrixBlock(g as Sel, x - SEQ_W / 2, cy - MAT_H / 2, {
    width: SEQ_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 5,
    dimTop: 'S',
    dimRight: 'D',
  });
}

function drawWeightMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.weight.fill,
  stroke = COLORS.weight.stroke,
  width = WEIGHT_W,
  height = WEIGHT_H
): void {
  drawMatrixBlock(g as Sel, x - width / 2, cy - height / 2, {
    width,
    height,
    label,
    sublabel,
    fill,
    stroke,
    cols: 5,
    rows: 5,
  });
}

function drawSmallVector(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill: string,
  stroke: string,
  width = VEC_W
): void {
  drawMatrixBlock(g as Sel, x - width / 2, cy - VEC_H / 2, {
    width,
    height: VEC_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 1,
  });
}

function drawBadge(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string): void {
  const badgeW = Math.max(80, text.length * 7 + 14);
  const badgeH = VEC_H;
  g.append('rect')
    .attr('x', cx - badgeW / 2)
    .attr('y', cy - badgeH / 2)
    .attr('width', badgeW)
    .attr('height', badgeH)
    .attr('rx', 6)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);
  lbl(g, cx, cy, text, { size: 10, weight: '600', color: stroke });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Parameter summary
// ═══════════════════════════════════════════════════════════════════════════════

function drawParamSummary(g: Gsel, cx: number, y: number, p: MambaParams): number {
  const SUM_W = 960;
  const SUM_H = 60;
  const grp = g.append('g').attr('transform', `translate(${cx - SUM_W / 2}, ${y})`);
  grp.append('rect')
    .attr('width', SUM_W)
    .attr('height', SUM_H)
    .attr('rx', 8)
    .attr('fill', 'var(--surface)')
    .attr('stroke', 'var(--border)')
    .attr('stroke-width', 1);
  lbl(grp, 14, 18, 'Parameters →', { size: 10, weight: '700', color: 'var(--text-muted)' });

  const items = [
    { label: `d_model=${p.dModel}`,      meta: 'hidden',    color: '#4caf50' },
    { label: `d_inner=${p.dInner}`,      meta: '2×d_model', color: '#1976d2' },
    { label: `seq_len=${p.seqLen}`,      meta: 'tokens',    color: '#7b1fa2' },
    { label: `state_dim=${p.stateDim}`,  meta: 'SSM state', color: '#c2185b' },
    { label: `Δ_rank=${p.deltaRank}`,    meta: 'delta proj',color: '#00838f' },
    { label: `variant=${p.variant}`,     meta: 'algorithm', color: '#009688' },
  ];
  const cols = 6;
  const itemW = Math.floor(SUM_W / cols);
  const startX = 8;
  const startY = 28;
  items.forEach((item, i) => {
    const col = i % cols;
    const px = startX + col * itemW;
    const py = startY;
    grp.append('rect')
      .attr('x', px)
      .attr('y', py)
      .attr('width', itemW - 8)
      .attr('height', 24)
      .attr('rx', 6)
      .attr('fill', hexWithAlpha(item.color, 0.08))
      .attr('stroke', item.color)
      .attr('stroke-width', 1);
    lbl(grp, px + 8, py + 9, item.label, { size: 9, weight: '600', color: item.color, font: 'monospace', anchor: 'start' });
    lbl(grp, px + 8, py + 20, `→ ${item.meta}`, { size: 7, color: item.color, anchor: 'start' });
  });
  return y + SUM_H + 14;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Shared steps: Input, InProj split, OutProj, Output, Residual
// ═══════════════════════════════════════════════════════════════════════════════

function drawInputStep(g: Gsel, cx: number, y: number, stepId: number, p: MambaParams): number {
  const grp = startGroup(g, 'step-mb-input', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'Input hidden states',
    `x ∈ ℝ^(B×S×${p.dModel})`,
    COLORS.input.fill, COLORS.input.stroke
  );
  const cy = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(grp, cx, cy, 'x', `[B, S, ${p.dModel}]`, COLORS.input.fill, COLORS.input.stroke);
  lbl(grp, cx, cy + MAT_H / 2 + 16, 'one hidden vector per token position', { size: 10, color: COLORS.muted });
  return cy + MAT_H / 2 + 30;
}

function drawOutputStep(g: Gsel, cx: number, y: number, stepId: number, p: MambaParams): number {
  const grp = startGroup(g, 'step-mb-output', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'Output hidden states',
    `out ∈ ℝ^(B×S×${p.dModel})`,
    COLORS.output.fill, COLORS.output.stroke
  );
  const cy = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(grp, cx, cy, 'out', `[B, S, ${p.dModel}]`, COLORS.output.fill, COLORS.output.stroke);
  lbl(grp, cx, cy + MAT_H / 2 + 16, 'passed to next block or final LM head', { size: 10, color: COLORS.muted });
  return cy + MAT_H / 2 + 30;
}

// Draw the input projection: x → [x_inner, z] split
// x_inner is centered at cx (main SSM flow); z is offset right (gate bypass)
function drawInProjStep(
  g: Gsel, cx: number, y: number, stepId: number, p: MambaParams,
  inputBottom: number
): { bottom: number; xCy: number; zCy: number; zX: number; residualStartY: number } {
  const grp = startGroup(g, 'step-mb-inproj', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'Input Projection',
    `[D→2×d_inner]`,
    COLORS.proj.fill, COLORS.proj.stroke
  );

  const residualStartY = inputBottom - 20;

  // Weight matrix centred
  const wCy = headerBottom + BOX_TO_ROW_GAP + WEIGHT_H / 2;
  const wW = 130;
  drawWeightMatrix(grp, cx, wCy, 'W_in', `[${p.dModel}, ${p.dInner * 2}]`, COLORS.weight.fill, COLORS.weight.stroke, wW, WEIGHT_H);
  arrowDown(grp, cx, inputBottom, wCy - WEIGHT_H / 2, COLORS.proj.stroke);
  lbl(grp, cx + wW / 2 + 8, wCy, '× W_in', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  // Projected vector → split into x_inner (centered) and z (right)
  const projY = wCy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  const projW = 170;
  drawSmallVector(grp, cx, projY, 'proj', `[B, S, ${p.dInner * 2}]`, COLORS.proj.fill, COLORS.proj.stroke, projW);
  arrowDown(grp, cx, wCy + WEIGHT_H / 2, projY - VEC_H / 2, COLORS.weight.stroke);

  // Split label
  const splitY = projY + VEC_H / 2 + 18;
  lbl(grp, cx, splitY, '── split along last dim ──', { size: 10, color: COLORS.muted, anchor: 'middle' });

  // x_inner centered at cx (main SSM flow)
  const outVecY = splitY + 32 + VEC_H / 2;
  drawSmallVector(grp, cx, outVecY, 'x_inner', `[B, S, ${p.dInner}]`, COLORS.proj.fill, COLORS.proj.stroke, 140);
  drawArrow(grp as Sel, cx, projY + VEC_H / 2, cx, outVecY - VEC_H / 2, { color: COLORS.proj.stroke });
  lbl(grp, cx, outVecY + VEC_H / 2 + 12, '→ SSM branch', { size: 9, color: COLORS.proj.stroke });

  // z gate vector offset right
  const zX = cx + 240;
  drawSmallVector(grp, zX, outVecY, 'z', `[B, S, ${p.dInner}]`, COLORS.gate.fill, COLORS.gate.stroke, 130);
  drawArrow(grp as Sel, cx + projW / 4, projY + VEC_H / 2, zX, outVecY - VEC_H / 2, { color: COLORS.gate.stroke });
  lbl(grp, zX, outVecY + VEC_H / 2 + 12, '→ gate branch', { size: 9, color: COLORS.gate.stroke });

  const bottom = outVecY + VEC_H / 2 + 26;
  return { bottom, xCy: outVecY, zCy: outVecY, zX, residualStartY };
}

// Residual add ⊕ with bypass path drawn
function drawResidualAdd(
  g: Gsel, cx: number, y: number, stepId: number,
  formula: string, label: string,
  residualStartY: number, dModel: number
): number {
  const grp = startGroup(g, 'step-mb-residual', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId, label, formula,
    COLORS.residual.fill, COLORS.residual.stroke
  );
  const addY = headerBottom + BOX_TO_ROW_GAP + 14;
  opCircle(grp, cx, addY, '⊕', COLORS.residual.stroke);

  const outY = addY + 14 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, outY, 'out', `[B, S, ${dModel}]`, COLORS.residual.fill, COLORS.residual.stroke, 140);
  arrowDown(grp, cx, addY + 14, outY - VEC_H / 2, COLORS.residual.stroke);

  // Residual bypass path
  const farX = CX + RESIDUAL_OFFSET;
  const bypassPath = `M ${cx},${residualStartY} L ${farX},${residualStartY} L ${farX},${addY} L ${cx + 14},${addY}`;
  g.append('path')
    .attr('d', bypassPath)
    .attr('fill', 'none')
    .attr('stroke', COLORS.residual.stroke)
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '5,3')
    .attr('opacity', 0.75);
  lbl(g, farX - 8, (residualStartY + addY) / 2, 'residual', { size: 10, color: COLORS.residual.stroke, anchor: 'end' });

  return outY + VEC_H / 2 + 10;
}

// Out projection
function drawOutProjStep(
  g: Gsel, cx: number, y: number, stepId: number, p: MambaParams, gatedBottom: number
): number {
  const grp = startGroup(g, 'step-mb-outproj', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'Output Projection',
    `[d_inner→D]`,
    COLORS.output.fill, COLORS.output.stroke
  );

  const wCy = headerBottom + BOX_TO_ROW_GAP + WEIGHT_H / 2;
  const wW = 120;
  drawWeightMatrix(grp, cx, wCy, 'W_out', `[${p.dInner}, ${p.dModel}]`, COLORS.weight.fill, COLORS.weight.stroke, wW, WEIGHT_H);
  arrowDown(grp, cx, gatedBottom, wCy - WEIGHT_H / 2, COLORS.gate.stroke);
  lbl(grp, cx + wW / 2 + 8, wCy, '× W_out', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  const outY = wCy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, outY, 'out_proj', `[B, S, ${p.dModel}]`, COLORS.output.fill, COLORS.output.stroke, 150);
  arrowDown(grp, cx, wCy + WEIGHT_H / 2, outY - VEC_H / 2, COLORS.weight.stroke);

  return outY + VEC_H / 2 + 20;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Mamba-1: conv1d + selective scan
// ═══════════════════════════════════════════════════════════════════════════════

function drawConv1dStep(
  g: Gsel, cx: number, y: number, stepId: number, p: MambaParams, xCy: number, _xInX: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-mb-conv', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'Depthwise Conv1d',
    `kernel=4, groups=d_inner`,
    COLORS.conv.fill, COLORS.conv.stroke
  );

  // conv kernel weight
  const kCy = headerBottom + BOX_TO_ROW_GAP + WEIGHT_H / 2;
  const kW = 110;
  const kH = 56;
  drawWeightMatrix(grp, cx, kCy, 'W_conv', `[d_inner, 1, 4]`, COLORS.weight.fill, COLORS.weight.stroke, kW, kH);
  // Arrow from x_inner output (above) down to conv kernel
  arrowDown(grp, cx, xCy + VEC_H / 2, kCy - kH / 2, COLORS.conv.stroke);
  lbl(grp, cx + kW / 2 + 8, kCy, 'depthwise k=4', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });
  lbl(grp, cx, kCy + kH / 2 + 12,
    'causal conv along S axis; mixes local context per channel', { size: 9, color: COLORS.muted });

  const convOutY = kCy + kH / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, convOutY, 'conv_out', `[B, S, ${p.dInner}]`, COLORS.conv.fill, COLORS.conv.stroke, 150);
  arrowDown(grp, cx, kCy + kH / 2, convOutY - VEC_H / 2, COLORS.weight.stroke);

  // SiLU badge
  const siluY = convOutY + VEC_H / 2 + ROW_EQ_GAP;
  drawBadge(grp, cx, siluY, 'SiLU', COLORS.conv.fill, COLORS.conv.stroke);
  arrowDown(grp, cx, convOutY + VEC_H / 2, siluY - VEC_H / 2, COLORS.conv.stroke);

  const actY = siluY + VEC_H / 2 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, actY, 'x_conv', `[B, S, ${p.dInner}]`, COLORS.conv.fill, COLORS.conv.stroke, 150);
  arrowDown(grp, cx, siluY + VEC_H / 2, actY - VEC_H / 2, COLORS.conv.stroke);

  return { bottom: actY + VEC_H / 2 + 20, outCy: actY };
}

function drawXProjStep(
  g: Gsel, cx: number, y: number, stepId: number, p: MambaParams, xConvBottom: number
): { bottom: number; deltaCy: number; bCy: number; cCy: number } {
  const grp = startGroup(g, 'step-mb-xproj', stepId);
  const projTotal = p.deltaRank + p.stateDim * 2;
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'SSM Parameter Projection',
    `x_proj: [d_inner→Δ_rank+2N]`,
    COLORS.delta.fill, COLORS.delta.stroke
  );

  const wCy = headerBottom + BOX_TO_ROW_GAP + WEIGHT_H / 2;
  const wW = 140;
  drawWeightMatrix(grp, cx, wCy, 'W_x', `[${p.dInner}, ${projTotal}]`, COLORS.weight.fill, COLORS.weight.stroke, wW, WEIGHT_H);
  arrowDown(grp, cx, xConvBottom, wCy - WEIGHT_H / 2, COLORS.conv.stroke);
  lbl(grp, cx + wW / 2 + 8, wCy, '× W_x', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  const xprojY = wCy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  const xprojW = 180;
  drawSmallVector(grp, cx, xprojY, 'x_proj', `[B, S, ${projTotal}]`, COLORS.delta.fill, COLORS.delta.stroke, xprojW);
  arrowDown(grp, cx, wCy + WEIGHT_H / 2, xprojY - VEC_H / 2, COLORS.weight.stroke);

  // Split into Δ, B, C
  const splitY = xprojY + VEC_H / 2 + 18;
  lbl(grp, cx, splitY, '── split: Δ_rank | N | N ──', { size: 10, color: COLORS.muted });

  const colGap = 240;
  const dX = cx - colGap;
  const bX = cx;
  const cX = cx + colGap;
  const paramY = splitY + 32 + VEC_H / 2;

  drawSmallVector(grp, dX, paramY, 'Δ_raw', `[B, S, ${p.deltaRank}]`, COLORS.delta.fill, COLORS.delta.stroke, 140);
  drawSmallVector(grp, bX, paramY, 'B_raw', `[B, S, ${p.stateDim}]`, COLORS.state.fill, COLORS.state.stroke, 130);
  drawSmallVector(grp, cX, paramY, 'C_raw', `[B, S, ${p.stateDim}]`, COLORS.state.fill, COLORS.state.stroke, 130);

  drawArrow(grp as Sel, cx - xprojW / 4, xprojY + VEC_H / 2, dX, paramY - VEC_H / 2, { color: COLORS.delta.stroke });
  drawArrow(grp as Sel, cx, xprojY + VEC_H / 2, bX, paramY - VEC_H / 2, { color: COLORS.state.stroke });
  drawArrow(grp as Sel, cx + xprojW / 4, xprojY + VEC_H / 2, cX, paramY - VEC_H / 2, { color: COLORS.state.stroke });

  // Δ goes through a linear + softplus to become the step size
  const dtY = paramY + VEC_H / 2 + ROW_EQ_GAP;
  drawBadge(grp, dX, dtY, 'Linear+Softplus', COLORS.delta.fill, COLORS.delta.stroke);
  arrowDown(grp, dX, paramY + VEC_H / 2, dtY - VEC_H / 2, COLORS.delta.stroke);
  lbl(grp, dX, dtY + VEC_H / 2 + 10, 'dt_proj: [Δ_rank→d_inner]', { size: 8, color: COLORS.muted, font: 'monospace' });

  const dtOutY = dtY + VEC_H / 2 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, dX, dtOutY, 'Δ', `[B, S, ${p.dInner}]`, COLORS.delta.fill, COLORS.delta.stroke, 130);
  arrowDown(grp, dX, dtY + VEC_H / 2, dtOutY - VEC_H / 2, COLORS.delta.stroke);
  lbl(grp, dX, dtOutY + VEC_H / 2 + 12, 'input-dependent step size', { size: 9, color: COLORS.muted });
  lbl(grp, bX, paramY + VEC_H / 2 + 12, 'input-dependent state proj', { size: 9, color: COLORS.muted });
  lbl(grp, cX, paramY + VEC_H / 2 + 12, 'input-dependent output proj', { size: 9, color: COLORS.muted });

  const bottom = Math.max(dtOutY + VEC_H / 2, paramY + VEC_H / 2) + 30;
  return { bottom, deltaCy: dtOutY, bCy: paramY, cCy: paramY };
}

function drawSelectiveScanStep(
  g: Gsel, cx: number, y: number, stepId: number, p: MambaParams,
  _xConvBottom: number, _deltaBottom: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-mb-ssm', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'Selective Scan (SSM)',
    `h_t = Ā·h_{t-1} + B̄·x_t`,
    COLORS.ssm.fill, COLORS.ssm.stroke
  );

  // Show A, B, C, Δ matrices in a 2×2 layout
  const matGap = 240;
  const matRow1Y = headerBottom + BOX_TO_ROW_GAP + WEIGHT_H / 2;

  const aX = cx - matGap;
  const bX = cx + matGap;
  const matRow2Y = matRow1Y + WEIGHT_H + ROW_EQ_GAP;

  const mW = 100;
  const mH = 64;

  // A matrix (learned, state transition)
  drawWeightMatrix(grp, aX, matRow1Y, 'A', `[d_inner, N]`, COLORS.ssm.fill, COLORS.ssm.stroke, mW, mH);
  lbl(grp, aX, matRow1Y + mH / 2 + 12, 'learned, state→state', { size: 8, color: COLORS.muted });

  // Δ (input-dep. step size)
  drawSmallVector(grp, bX, matRow1Y, 'Δ', `[B, S, ${p.dInner}]`, COLORS.delta.fill, COLORS.delta.stroke, 130);
  lbl(grp, bX, matRow1Y + VEC_H / 2 + 14, 'input-dependent step size', { size: 8, color: COLORS.muted });

  // ZOH discretise: Ā = exp(Δ·A)
  const discY = matRow1Y + Math.max(mH, VEC_H) / 2 + ROW_EQ_GAP + VEC_H / 2;
  lbl(grp, cx, discY - VEC_H / 2 - 8,
    'Discretise (ZOH): Ā = exp(Δ⊙A),  B̄ = (Ā-I)·A⁻¹·B',
    { size: 9, color: COLORS.ssm.stroke, font: 'monospace' });
  drawArrow(grp as Sel, aX, matRow1Y + mH / 2, aX, discY - VEC_H / 2, { color: COLORS.ssm.stroke });
  drawArrow(grp as Sel, bX, matRow1Y + VEC_H / 2, bX, discY - VEC_H / 2, { color: COLORS.delta.stroke });

  // B input projection (from x_proj)
  const bProjX = cx - matGap;
  const bCY = matRow2Y;
  drawSmallVector(grp, bProjX, bCY, 'B', `[B, S, ${p.stateDim}]`, COLORS.state.fill, COLORS.state.stroke, 130);
  lbl(grp, bProjX, bCY + VEC_H / 2 + 12, 'input→state projection', { size: 8, color: COLORS.muted });

  // C output projection
  const cX2 = cx + matGap;
  drawSmallVector(grp, cX2, bCY, 'C', `[B, S, ${p.stateDim}]`, COLORS.state.fill, COLORS.state.stroke, 130);
  lbl(grp, cX2, bCY + VEC_H / 2 + 12, 'state→output projection', { size: 8, color: COLORS.muted });

  // Recurrence box
  const recBoxW = 460;
  const recBoxH = 60;
  const recBoxX = cx - recBoxW / 2;
  const recBoxY = discY + VEC_H / 2 + ROW_EQ_GAP;
  grp.append('rect')
    .attr('x', recBoxX)
    .attr('y', recBoxY)
    .attr('width', recBoxW)
    .attr('height', recBoxH)
    .attr('rx', 8)
    .attr('fill', hexWithAlpha(COLORS.ssm.stroke, 0.06))
    .attr('stroke', COLORS.ssm.stroke)
    .attr('stroke-width', 1.5);
  lbl(grp, cx, recBoxY + 18, 'h_t = Ā · h_{t-1}  +  B̄ · x_t', { size: 11, weight: '700', color: COLORS.ssm.stroke, font: 'monospace' });
  lbl(grp, cx, recBoxY + 38, 'y_t = C · h_t  +  D · x_t', { size: 11, weight: '700', color: COLORS.ssm.stroke, font: 'monospace' });

  // Arrows into recurrence
  drawArrow(grp as Sel, cx - matGap, discY + VEC_H / 2, recBoxX + 40, recBoxY, { color: COLORS.ssm.stroke });
  drawArrow(grp as Sel, bProjX, bCY + VEC_H / 2, recBoxX + 80, recBoxY + recBoxH, { color: COLORS.state.stroke });
  drawArrow(grp as Sel, cX2, bCY + VEC_H / 2, recBoxX + recBoxW - 80, recBoxY + recBoxH, { color: COLORS.state.stroke });

  const ssmOutY = recBoxY + recBoxH + ROW_EQ_GAP + VEC_H / 2;
  drawSmallVector(grp, cx, ssmOutY, 'ssm_out', `[B, S, ${p.dInner}]`, COLORS.ssm.fill, COLORS.ssm.stroke, 150);
  arrowDown(grp, cx, recBoxY + recBoxH, ssmOutY - VEC_H / 2, COLORS.ssm.stroke);
  lbl(grp, cx + 80, ssmOutY, 'y = C·h + D·x', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  return { bottom: ssmOutY + VEC_H / 2 + 20, outCy: ssmOutY };
}

function drawGatingStep(
  g: Gsel, cx: number, y: number, stepId: number, p: MambaParams,
  ssmBottom: number, _gateLabel: string, zBypassX?: number, zBypassY?: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-mb-gate', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'Gated Multiply',
    `gated = ssm_out ⊙ SiLU(z)`,
    COLORS.gate.fill, COLORS.gate.stroke
  );

  // SiLU of z (gate)
  const siluX = cx + 240;
  const siluY = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  drawBadge(grp, siluX, siluY, 'SiLU(z)', COLORS.gate.fill, COLORS.gate.stroke);
  lbl(grp, siluX, siluY + VEC_H / 2 + 12, 'gate activation', { size: 9, color: COLORS.muted });

  // ⊙ circle between ssm_out and gate
  const mulCircleY = siluY + VEC_H / 2 + ROW_EQ_GAP;
  opCircle(grp, cx, mulCircleY, '⊙', COLORS.gate.stroke);
  // Single arrow from SSM output (above) down to ⊙ circle
  drawArrow(grp as Sel, cx, ssmBottom, cx - 14, mulCircleY, { color: COLORS.ssm.stroke });
  // Arrow from SiLU(z) to ⊙ circle
  drawArrow(grp as Sel, siluX, siluY + VEC_H / 2, cx + 14, mulCircleY, { color: COLORS.gate.stroke });

  // z bypass: dashed line from InProj's z to SiLU(z) badge
  if (zBypassX !== undefined && zBypassY !== undefined) {
    const farX = CX + RESIDUAL_OFFSET + 40;
    g.append('path')
      .attr('d', `M ${zBypassX},${zBypassY} L ${farX},${zBypassY} L ${farX},${siluY} L ${siluX + 50},${siluY}`)
      .attr('fill', 'none')
      .attr('stroke', COLORS.gate.stroke)
      .attr('stroke-width', 1.5)
      .attr('stroke-dasharray', '5,3')
      .attr('opacity', 0.6);
    lbl(g, farX - 8, (zBypassY + siluY) / 2, 'z (gate)', { size: 9, color: COLORS.gate.stroke, anchor: 'end' });
  }

  const gatedY = mulCircleY + 14 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, gatedY, 'gated', `[B, S, ${p.dInner}]`, COLORS.gate.fill, COLORS.gate.stroke, 140);
  arrowDown(grp, cx, mulCircleY + 14, gatedY - VEC_H / 2, COLORS.gate.stroke);
  lbl(grp, cx + 80, gatedY, '⊙ element-wise', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  return { bottom: gatedY + VEC_H / 2 + 20, outCy: gatedY };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Mamba-2 (SSD) steps
// ═══════════════════════════════════════════════════════════════════════════════

function drawSSDProjStep(
  g: Gsel, cx: number, y: number, stepId: number, p: MambaParams, xConvBottom: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-mb-ssdproj', stepId);
  const projTotal = p.deltaRank + p.stateDim * 2;
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'SSD Parameter Projection',
    `[d_inner→Δ_rank+2N]`,
    COLORS.delta.fill, COLORS.delta.stroke
  );

  const wCy = headerBottom + BOX_TO_ROW_GAP + WEIGHT_H / 2;
  const wW = 140;
  drawWeightMatrix(grp, cx, wCy, 'W_x', `[${p.dInner * 2}, ${projTotal}]`, COLORS.weight.fill, COLORS.weight.stroke, wW, WEIGHT_H);
  arrowDown(grp, cx, xConvBottom, wCy - WEIGHT_H / 2, COLORS.proj.stroke);

  const xprojY = wCy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  const xprojW = 180;
  drawSmallVector(grp, cx, xprojY, 'ssd_proj', `[B, S, ${projTotal}]`, COLORS.delta.fill, COLORS.delta.stroke, xprojW);
  arrowDown(grp, cx, wCy + WEIGHT_H / 2, xprojY - VEC_H / 2, COLORS.weight.stroke);
  lbl(grp, cx, xprojY + VEC_H / 2 + 14,
    `projects to: Δ=[B,S,${p.deltaRank}]  B=[B,S,${p.stateDim}]  C=[B,S,${p.stateDim}]`,
    { size: 9, color: COLORS.muted, font: 'monospace' });

  return { bottom: xprojY + VEC_H / 2 + 30, outCy: xprojY };
}

function drawSSDStep(
  g: Gsel, cx: number, y: number, stepId: number, p: MambaParams, projBottom: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-mb-ssd', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'Structured State Space Duality (SSD)',
    `y = SSM(Δ, A, B, C) · x`,
    COLORS.ssm.fill, COLORS.ssm.stroke
  );

  // SSD overview box
  const ssdBoxW = 560;
  const ssdBoxH = 100;
  const ssdBoxX = cx - ssdBoxW / 2;
  const ssdBoxY = headerBottom + BOX_TO_ROW_GAP;
  grp.append('rect')
    .attr('x', ssdBoxX)
    .attr('y', ssdBoxY)
    .attr('width', ssdBoxW)
    .attr('height', ssdBoxH)
    .attr('rx', 8)
    .attr('fill', hexWithAlpha(COLORS.ssm.stroke, 0.05))
    .attr('stroke', COLORS.ssm.stroke)
    .attr('stroke-width', 1.5);
  lbl(grp, cx, ssdBoxY + 18, 'M = diag(exp(Δ⊙A))', { size: 10, weight: '700', color: COLORS.ssm.stroke, font: 'monospace' });
  lbl(grp, cx, ssdBoxY + 40, 'L = lower-triangular mask (causal)', { size: 9, color: COLORS.muted, font: 'monospace' });
  lbl(grp, cx, ssdBoxY + 60, 'Y = (L ⊙ C·B^T) · (M · X)', { size: 10, weight: '700', color: COLORS.ssm.stroke, font: 'monospace' });
  lbl(grp, cx, ssdBoxY + 80, 'equivalent to selective recurrence, parallel over S', { size: 9, color: COLORS.muted });

  arrowDown(grp, cx, projBottom, ssdBoxY, COLORS.delta.stroke);

  const ssdOutY = ssdBoxY + ssdBoxH + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, ssdOutY, 'ssd_out', `[B, S, ${p.dInner}]`, COLORS.ssm.fill, COLORS.ssm.stroke, 150);
  arrowDown(grp, cx, ssdBoxY + ssdBoxH, ssdOutY - VEC_H / 2, COLORS.ssm.stroke);

  return { bottom: ssdOutY + VEC_H / 2 + 20, outCy: ssdOutY };
}

function drawSSDGatingStep(
  g: Gsel, cx: number, y: number, stepId: number, p: MambaParams, _ssdBottom: number,
  zBypassX?: number, zBypassY?: number
): { bottom: number; outCy: number } {
  const grp = startGroup(g, 'step-mb-ssdgate', stepId);
  const headerBottom = stepHeader(
    grp, cx, y, stepId,
    'Gated Multiply',
    `gated = ssd_out ⊙ SiLU(z)`,
    COLORS.gate.fill, COLORS.gate.stroke
  );

  const siluX = cx + 240;
  const siluY = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  drawBadge(grp, siluX, siluY, 'SiLU(z)', COLORS.gate.fill, COLORS.gate.stroke);

  const mulCircleY = siluY + VEC_H / 2 + ROW_EQ_GAP;
  opCircle(grp, cx, mulCircleY, '⊙', COLORS.gate.stroke);
  // Arrow from SSD output (above) down to ⊙ circle
  drawArrow(grp as Sel, cx, _ssdBottom, cx - 14, mulCircleY, { color: COLORS.ssm.stroke });
  drawArrow(grp as Sel, siluX, siluY + VEC_H / 2, cx + 14, mulCircleY, { color: COLORS.gate.stroke });

  // z bypass: dashed line from InProj's z to SiLU(z) badge
  if (zBypassX !== undefined && zBypassY !== undefined) {
    const farX = CX + RESIDUAL_OFFSET + 40;
    g.append('path')
      .attr('d', `M ${zBypassX},${zBypassY} L ${farX},${zBypassY} L ${farX},${siluY} L ${siluX + 50},${siluY}`)
      .attr('fill', 'none')
      .attr('stroke', COLORS.gate.stroke)
      .attr('stroke-width', 1.5)
      .attr('stroke-dasharray', '5,3')
      .attr('opacity', 0.6);
    lbl(g, farX - 8, (zBypassY + siluY) / 2, 'z (gate)', { size: 9, color: COLORS.gate.stroke, anchor: 'end' });
  }

  const gatedY = mulCircleY + 14 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, gatedY, 'gated', `[B, S, ${p.dInner}]`, COLORS.gate.fill, COLORS.gate.stroke, 140);
  arrowDown(grp, cx, mulCircleY + 14, gatedY - VEC_H / 2, COLORS.gate.stroke);

  return { bottom: gatedY + VEC_H / 2 + 20, outCy: gatedY };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Variant renderers
// ═══════════════════════════════════════════════════════════════════════════════

function renderMamba1(g: Gsel, cx: number, y: number, p: MambaParams): RenderResult {
  const steps: MambaStep[] = [];
  let stepId = 1;

  // Step 1: Input
  const inputBottom = drawInputStep(g, cx, y, stepId, p);
  steps.push(makeStep(stepId, 'Input', 'Input hidden states', `x ∈ ℝ^(B×S×${p.dModel})`,
    'Input token hidden states to the Mamba block.', 'step-mb-input', COLORS.input.stroke, COLORS.input.fill));
  stepId++;
  y = inputBottom + GROUP_GAP;

  // Step 2: InProj
  const residualStartY = inputBottom - 30;
  const inproj = drawInProjStep(g, cx, y, stepId, p, inputBottom);
  steps.push(makeStep(stepId, 'InProj', 'Input Projection', `proj = x @ W_in`,
    'Projects input to 2×d_inner and splits into SSM branch (x_inner) and gate (z).', 'step-mb-inproj', COLORS.proj.stroke, COLORS.proj.fill));
  stepId++;
  y = inproj.bottom + GROUP_GAP;

  // Step 3: Conv1d — x_inner is centered at cx, arrow flows straight down
  const conv = drawConv1dStep(g, cx, y, stepId, p, inproj.xCy, 0);
  steps.push(makeStep(stepId, 'Conv1d', 'Depthwise Conv1d', `x_conv = SiLU(Conv1d(x_inner))`,
    'Causal depthwise conv1d (kernel=4) mixes local temporal context per channel before the SSM.', 'step-mb-conv', COLORS.conv.stroke, COLORS.conv.fill));
  stepId++;
  y = conv.bottom + GROUP_GAP;

  // Step 4: x_proj
  const xproj = drawXProjStep(g, cx, y, stepId, p, conv.bottom);
  steps.push(makeStep(stepId, 'x_proj', 'SSM Parameter Projection', `[Δ_raw, B_raw, C_raw] = x_conv @ W_x`,
    'Projects conv output to Δ (step size), B (input projection), C (output projection) — all input-dependent.', 'step-mb-xproj', COLORS.delta.stroke, COLORS.delta.fill));
  stepId++;
  y = xproj.bottom + GROUP_GAP;

  // Step 5: Selective scan
  const scan = drawSelectiveScanStep(g, cx, y, stepId, p, conv.outCy, xproj.deltaCy);
  steps.push(makeStep(stepId, 'SSM', 'Selective Scan', `h_t = Ā·h_{t-1} + B̄·x_t,  y_t = C·h_t`,
    'Recurrent selective scan: A is fixed, but Δ, B, C are input-dependent, enabling the model to selectively remember or forget.', 'step-mb-ssm', COLORS.ssm.stroke, COLORS.ssm.fill));
  stepId++;
  y = scan.bottom + GROUP_GAP;

  // Step 6: Gating — pass z bypass coordinates from InProj
  const gate = drawGatingStep(g, cx, y, stepId, p, scan.outCy, 'z', inproj.zX, inproj.zCy);
  steps.push(makeStep(stepId, 'Gate', 'Gated Multiply', `gated = ssm_out ⊙ SiLU(z)`,
    'Element-wise multiply of the SSM output with the SiLU-activated gate (z), controlling information flow.', 'step-mb-gate', COLORS.gate.stroke, COLORS.gate.fill));
  stepId++;
  y = gate.bottom + GROUP_GAP;

  // Step 7: Out proj
  const outproj = drawOutProjStep(g, cx, y, stepId, p, gate.outCy + VEC_H / 2 + 20);
  steps.push(makeStep(stepId, 'OutProj', 'Output Projection', `out_proj = gated @ W_out`,
    'Projects gated output back to d_model dimension.', 'step-mb-outproj', COLORS.output.stroke, COLORS.output.fill));
  stepId++;
  y = outproj + GROUP_GAP;

  // Step 8: Residual
  const resBottom = drawResidualAdd(g, cx, y, stepId,
    'out = x + out_proj', 'Residual Add',
    residualStartY, p.dModel);
  steps.push(makeStep(stepId, 'Residual', 'Residual Connection', `out = x + out_proj`,
    'Adds the original input back to the block output via a skip connection.', 'step-mb-residual', COLORS.residual.stroke, COLORS.residual.fill));
  stepId++;
  y = resBottom + GROUP_GAP;

  // Step 9: Output
  const outputBottom = drawOutputStep(g, cx, y, stepId, p);
  steps.push(makeStep(stepId, 'Output', 'Output hidden states', `out ∈ ℝ^(B×S×${p.dModel})`,
    'Block output passed to the next layer.', 'step-mb-output', COLORS.output.stroke, COLORS.output.fill));

  return { steps, y: outputBottom };
}

function renderMamba2(g: Gsel, cx: number, y: number, p: MambaParams): RenderResult {
  const steps: MambaStep[] = [];
  let stepId = 1;

  // Step 1: Input
  const inputBottom = drawInputStep(g, cx, y, stepId, p);
  steps.push(makeStep(stepId, 'Input', 'Input hidden states', `x ∈ ℝ^(B×S×${p.dModel})`,
    'Input token hidden states.', 'step-mb-input', COLORS.input.stroke, COLORS.input.fill));
  stepId++;
  y = inputBottom + GROUP_GAP;

  // Step 2: InProj
  const residualStartY = inputBottom - 30;
  const inproj = drawInProjStep(g, cx, y, stepId, p, inputBottom);
  steps.push(makeStep(stepId, 'InProj', 'Input Projection', `proj = x @ W_in`,
    'Projects input to 2×d_inner; splits into x_inner (SSD branch) and z (gate branch).', 'step-mb-inproj', COLORS.proj.stroke, COLORS.proj.fill));
  stepId++;
  y = inproj.bottom + GROUP_GAP;

  // Step 3: SSD proj (no conv1d in Mamba-2)
  const ssdproj = drawSSDProjStep(g, cx, y, stepId, p, inproj.bottom);
  steps.push(makeStep(stepId, 'SSD Proj', 'SSD Parameter Projection', `[Δ_raw, B_raw, C_raw] = proj @ W_x`,
    'Projects the full concatenated projection to SSM parameters Δ, B, C (Mamba-2 skips the depthwise conv).', 'step-mb-ssdproj', COLORS.delta.stroke, COLORS.delta.fill));
  stepId++;
  y = ssdproj.bottom + GROUP_GAP;

  // Step 4: SSD
  const ssd = drawSSDStep(g, cx, y, stepId, p, ssdproj.bottom);
  steps.push(makeStep(stepId, 'SSD', 'Structured State Space Duality', `Y = SSD(Δ, A, B, C, x_inner)`,
    'SSD rewrites the selective recurrence as a structured semiseparable matrix multiply, enabling fully parallel training.', 'step-mb-ssd', COLORS.ssm.stroke, COLORS.ssm.fill));
  stepId++;
  y = ssd.bottom + GROUP_GAP;

  // Step 5: Gating — pass z bypass coordinates from InProj
  const gate = drawSSDGatingStep(g, cx, y, stepId, p, ssd.outCy, inproj.zX, inproj.zCy);
  steps.push(makeStep(stepId, 'Gate', 'Gated Multiply', `gated = ssd_out ⊙ SiLU(z)`,
    'Gates the SSD output with a SiLU-activated learned gate, controlling output information flow.', 'step-mb-ssdgate', COLORS.gate.stroke, COLORS.gate.fill));
  stepId++;
  y = gate.bottom + GROUP_GAP;

  // Step 6: Out proj
  const outproj = drawOutProjStep(g, cx, y, stepId, p, gate.outCy + VEC_H / 2 + 20);
  steps.push(makeStep(stepId, 'OutProj', 'Output Projection', `out_proj = gated @ W_out`,
    'Projects back to d_model.', 'step-mb-outproj', COLORS.output.stroke, COLORS.output.fill));
  stepId++;
  y = outproj + GROUP_GAP;

  // Step 7: Residual
  const resBottom = drawResidualAdd(g, cx, y, stepId,
    'out = x + out_proj', 'Residual Add',
    residualStartY, p.dModel);
  steps.push(makeStep(stepId, 'Residual', 'Residual Connection', `out = x + out_proj`,
    'Skip connection adds the original input to the block output.', 'step-mb-residual', COLORS.residual.stroke, COLORS.residual.fill));
  stepId++;
  y = resBottom + GROUP_GAP;

  // Step 8: Output
  const outputBottom = drawOutputStep(g, cx, y, stepId, p);
  steps.push(makeStep(stepId, 'Output', 'Output hidden states', `out ∈ ℝ^(B×S×${p.dModel})`,
    'Block output.', 'step-mb-output', COLORS.output.stroke, COLORS.output.fill));

  return { steps, y: outputBottom };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Step factory helper
// ═══════════════════════════════════════════════════════════════════════════════

function makeStep(
  id: number,
  shortLabel: string,
  label: string,
  formula: string,
  explanation: string,
  svgGroup: string,
  color: string,
  fill: string,
  codeLines?: string[]
): MambaStep {
  return {
    id,
    label,
    shortLabel,
    formula,
    explanation,
    code: { title: label, lines: codeLines || [`# ${formula}`] },
    svgGroup,
    color,
    fill,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Parameter / FLOP math
// ═══════════════════════════════════════════════════════════════════════════════

function computeMetrics(p: MambaParams) {
  const inProjParams = p.dModel * (p.dInner * 2);
  const conv1dParams = p.dInner * 4; // depthwise kernel
  const xProjParams = p.dInner * (p.deltaRank + p.stateDim * 2);
  const dtProjParams = p.deltaRank * p.dInner;
  const aParams = p.dInner * p.stateDim; // log_A
  const dParams = p.dInner; // D (skip connection)
  const outProjParams = p.dInner * p.dModel;

  const mamba1Params = inProjParams + conv1dParams + xProjParams + dtProjParams + aParams + dParams + outProjParams;
  const mamba2Params = inProjParams + xProjParams + dtProjParams + aParams + dParams + outProjParams;
  const totalParams = p.variant === 'mamba2' ? mamba2Params : mamba1Params;

  const flopsPerSeq = p.seqLen * (2 * p.dModel * p.dInner * 2 + 2 * p.dInner * (p.deltaRank + p.stateDim * 2) + 2 * p.dInner * p.stateDim + 2 * p.dInner * p.dModel);

  return { inProjParams, conv1dParams, xProjParams, dtProjParams, aParams, dParams, outProjParams, totalParams, flopsPerSeq };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main entry
// ═══════════════════════════════════════════════════════════════════════════════

export function renderMambaDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const dModel = Number(params.d_model) || 512;
  const seqLen = Number(params.seq_len) || 128;
  const stateDim = Number(params.state_dim) || 16;
  const variant = String(params.variant || 'mamba1');
  const dInner = dModel * 2;
  const deltaRank = 16;

  const p: MambaParams = { dModel, seqLen, stateDim, dInner, deltaRank, variant };

  const root = g as unknown as Gsel;
  let y = 28;

  // Title
  lbl(root, CX, y, 'Mamba Block', { size: 18, weight: '700', color: COLORS.text });
  y += 20;
  lbl(root, CX, y,
    `${variant === 'mamba2' ? 'Mamba-2 (SSD)' : 'Mamba-1 (conv1d + selective scan)'} · d_model=${dModel} · d_inner=${dInner} · seq_len=${seqLen} · state_dim=${stateDim} · Δ_rank=${deltaRank}`,
    { size: 11, color: COLORS.muted });
  y += 26;

  // Param summary
  y = drawParamSummary(root, CX, y, p);
  y += 14;

  // Variant diagram
  let result: RenderResult;
  if (variant === 'mamba2') {
    result = renderMamba2(root, CX, y, p);
  } else {
    result = renderMamba1(root, CX, y, p);
  }

  let footerY = result.y + 18;

  // Metrics line
  const metrics = computeMetrics(p);
  lbl(root, CX, footerY + 14,
    `Params: ${fmtNum(metrics.totalParams)} (in_proj ${fmtNum(metrics.inProjParams)} + x_proj ${fmtNum(metrics.xProjParams)} + out_proj ${fmtNum(metrics.outProjParams)}) · ~${fmtNum(metrics.flopsPerSeq)} FLOPs`,
    { size: 11, color: COLORS.muted, font: 'monospace' });
  footerY += 34;

  // Explanations
  const insightText = variant === 'mamba2'
    ? 'Mamba-2 replaces the depthwise conv1d with a structured state-space duality (SSD) formulation that is mathematically equivalent to the selective SSM but can be computed as a semiseparable matrix multiply, enabling full hardware parallelism during training.'
    : 'Mamba-1 uses a causal depthwise conv1d (kernel=4) to mix local context before the selective SSM. Unlike attention, the SSM parameters (Δ, B, C) are input-dependent, enabling selective compression of long sequences into a fixed-size state — O(L) memory vs O(L²) for attention.';

  const perfText = variant === 'mamba2'
    ? `SSD runs in O(L·d·N) FLOPs vs O(L²·d) for attention (L=${seqLen}, d=${dModel}, N=${stateDim}). For L>256 Mamba-2 is typically faster than full attention; for L<128 hardware utilization is the bottleneck.`
    : `Mamba-1 inference is O(1) per step (constant KV-cache) since it uses a recurrent state of size d_inner×N (=${dInner}×${stateDim}=${dInner * stateDim} floats). Training uses parallel scan for O(L log L) compute.`;

  footerY = drawExplanation(g, 80, footerY, W - 160, insightText, 'insight');
  footerY = drawExplanation(g, 80, footerY, W - 160, perfText, 'perf');
  footerY += 12;

  // Code annotation
  const codeLines = variant === 'mamba2' ? [
    `# Mamba-2 (SSD) forward`,
    `proj = x @ W_in        # [B, S, ${dInner * 2}]`,
    `x_inner, z = proj.split([${dInner}, ${dInner}], dim=-1)`,
    `ssd_proj = proj @ W_x  # [B, S, ${deltaRank + stateDim * 2}]`,
    `delta_raw, B_raw, C_raw = ssd_proj.split([${deltaRank}, ${stateDim}, ${stateDim}], dim=-1)`,
    `delta = F.softplus(delta_raw @ W_dt)  # [B, S, ${dInner}]`,
    `# Discretise: A_bar = exp(delta * A)`,
    `y = ssd(delta, A_bar, B_raw, C_raw, x_inner)  # structured semiseparable matmul`,
    `gated = y * F.silu(z)`,
    `out_proj = gated @ W_out  # [B, S, ${dModel}]`,
    `return x + out_proj  # residual`,
  ] : [
    `# Mamba-1 forward`,
    `proj = x @ W_in            # [B, S, ${dInner * 2}]`,
    `x_inner, z = proj.split([${dInner}, ${dInner}], dim=-1)`,
    `x_conv = F.silu(conv1d(x_inner))  # depthwise k=4`,
    `x_proj_out = x_conv @ W_x  # [B, S, ${deltaRank + stateDim * 2}]`,
    `delta_raw, B_raw, C_raw = x_proj_out.split([${deltaRank}, ${stateDim}, ${stateDim}], dim=-1)`,
    `delta = F.softplus(delta_raw @ W_dt)  # [B, S, ${dInner}]`,
    `A_bar = torch.exp(delta.unsqueeze(-1) * A)  # ZOH discretise`,
    `ssm_out = selective_scan(x_conv, delta, A_bar, B_raw, C_raw, D)`,
    `gated = ssm_out * F.silu(z)`,
    `out_proj = gated @ W_out   # [B, S, ${dModel}]`,
    `return x + out_proj  # residual`,
  ];

  footerY = drawCodeAnnotation(
    g, 80, footerY, W - 160,
    `Mamba Block — ${variant === 'mamba2' ? 'Mamba-2 (SSD)' : 'Mamba-1'}`,
    [`Params: ${fmtNum(metrics.totalParams)} · ~${fmtNum(metrics.flopsPerSeq)} FLOPs`],
    codeLines
  );

  return { width: W, height: footerY + 24, steps: result.steps };
}
